const o=[{id:"blood-basics-001",topicId:"blood-basics",question:"К какому типу тканей относится кровь?",options:["Жидкая соединительная ткань","Эпителиальная ткань","Мышечная ткань","Нервная ткань"],correctIndex:0,explanation:"Кровь — это жидкая соединительная ткань внутренней среды организма, обеспечивающая транспорт веществ, защиту, регуляцию гомеостаза и терморегуляцию.",difficulty:"easy",tags:["кровь","определение","ткань"]},{id:"blood-basics-002",topicId:"blood-basics",question:"Какую долю от массы тела составляет общий объём крови у взрослого человека?",options:["6–8%","1–2%","15–20%","30–35%"],correctIndex:0,explanation:"Общий объём крови у взрослого человека составляет 6–8% массы тела.",difficulty:"medium",tags:["кровь","объём","норма"]},{id:"blood-basics-003",topicId:"blood-basics",question:"Каков ориентировочный объём крови у женщин?",options:["≈ 4–5 л","≈ 5–6 л","≈ 2–3 л","≈ 7–8 л"],correctIndex:0,explanation:"Объём крови у женщин составляет приблизительно 4–5 л, у мужчин — 5–6 л.",difficulty:"medium",tags:["кровь","объём","женщины"]},{id:"blood-basics-004",topicId:"blood-basics",question:"Каков ориентировочный объём крови у мужчин?",options:["≈ 5–6 л","≈ 4–5 л","≈ 3–4 л","≈ 8–9 л"],correctIndex:0,explanation:"Объём крови у мужчин составляет приблизительно 5–6 л, у женщин — 4–5 л.",difficulty:"medium",tags:["кровь","объём","мужчины"]},{id:"blood-basics-005",topicId:"blood-basics",question:"Потеря какого объёма крови считается жизнеугрожающим состоянием?",options:["40% и более","10% и более","20% и более","5% и более"],correctIndex:0,explanation:"Потеря 40% и более крови — жизнеугрожающее состояние.",difficulty:"medium",tags:["кровь","кровопотеря","клиника"]},{id:"blood-basics-006",topicId:"blood-basics",question:"Какая из перечисленных НЕ относится к функциям крови согласно материалу?",options:["Пищеварительная","Транспортная","Защитная","Терморегуляторная"],correctIndex:0,explanation:"К функциям крови относятся транспортная, защитная, регуляторная и терморегуляторная. Пищеварительной функции среди них нет.",difficulty:"medium",tags:["кровь","функции","найди ошибку"]},{id:"blood-basics-007",topicId:"blood-basics",question:"Что из перечисленного относится к транспортной функции крови?",options:["Перенос O₂ и CO₂, питательных веществ, гормонов и метаболитов","Поддержание pH и осмотического давления","Иммунная защита с помощью лейкоцитов и антител","Отдача тепла через кожу"],correctIndex:0,explanation:"Транспортная функция крови включает перенос O₂ и CO₂, транспорт питательных веществ, перенос гормонов и метаболитов.",difficulty:"medium",tags:["кровь","функции","транспортная"]},{id:"blood-basics-008",topicId:"blood-basics",question:"Какие компоненты обеспечивают защитную функцию крови?",options:["Лейкоциты и антитела (иммунитет), тромбоциты и факторы свёртывания (гемостаз)","Только эритроциты","Только вода плазмы","Глюкоза и электролиты"],correctIndex:0,explanation:"Защитная функция включает иммунную защиту (лейкоциты, антитела) и гемостаз (тромбоциты, факторы свёртывания).",difficulty:"medium",tags:["кровь","функции","защитная"]},{id:"blood-basics-009",topicId:"blood-basics",question:"Что относится к регуляторной функции крови?",options:["Поддержание pH, осмотического и онкотического давления","Перенос кислорода к тканям","Образование тромбоцитарной пробки","Выработка антител"],correctIndex:0,explanation:"Регуляторная функция крови — это поддержание pH, осмотического и онкотического давления.",difficulty:"medium",tags:["кровь","функции","регуляторная"]},{id:"blood-basics-010",topicId:"blood-basics",question:"Какое соотношение плазмы и форменных элементов в крови?",options:["Плазма ~55%, форменные элементы ~45%","Плазма ~45%, форменные элементы ~55%","Плазма ~90%, форменные элементы ~10%","Плазма ~25%, форменные элементы ~75%"],correctIndex:0,explanation:"Кровь состоит из плазмы (~55%) и форменных элементов (~45%).",difficulty:"medium",tags:["кровь","состав","плазма"]},{id:"blood-basics-011",topicId:"blood-basics",question:"Какую долю плазмы составляет вода?",options:["90–92%","70–75%","55–60%","40–45%"],correctIndex:0,explanation:"В составе плазмы вода составляет 90–92%, белки — 7–8%.",difficulty:"medium",tags:["плазма","состав","вода"]},{id:"blood-basics-012",topicId:"blood-basics",question:"Какую долю плазмы составляют белки?",options:["7–8%","20–25%","0,5–1%","40–45%"],correctIndex:0,explanation:"Белки составляют 7–8% плазмы; к ним относятся альбумины, глобулины и фибриноген.",difficulty:"medium",tags:["плазма","состав","белки"]},{id:"blood-basics-013",topicId:"blood-basics",question:"Какие из перечисленных белков относятся к белкам плазмы крови?",options:["Альбумины, глобулины, фибриноген","Кератин, коллаген, эластин","Миозин, актин, тропонин","Инсулин, глюкагон, адреналин"],correctIndex:0,explanation:"К белкам плазмы крови относятся альбумины, глобулины и фибриноген.",difficulty:"medium",tags:["плазма","белки","альбумины"]},{id:"blood-basics-014",topicId:"blood-basics",question:"Какой белок плазмы относится к факторам свёртывания и образует фибрин при свёртывании крови?",options:["Фибриноген","Альбумин","Глобулин","Гемоглобин"],correctIndex:0,explanation:"Фибриноген — белок плазмы, относящийся к факторам свёртывания, из которого при свёртывании крови образуется фибрин.",difficulty:"hard",tags:["плазма","фибриноген","свёртывание"]},{id:"blood-basics-015",topicId:"blood-basics",question:"Что такое гемопоэз?",options:["Процесс образования и развития форменных элементов крови","Процесс разрушения эритроцитов","Процесс свёртывания крови","Процесс переноса кислорода гемоглобином"],correctIndex:0,explanation:"Гемопоэз — это процесс образования и развития форменных элементов крови.",difficulty:"medium",tags:["гемопоэз","определение"]},{id:"blood-basics-016",topicId:"blood-basics",question:"Где осуществляется гемопоэз?",options:["В красном костном мозге, а также в селезёнке и лимфатических узлах","Только в печени","В жёлтом костном мозге и почках","В стенках кровеносных сосудов"],correctIndex:0,explanation:"Гемопоэз осуществляется в красном костном мозге, а также в органах иммунной системы (селезёнка, лимфатические узлы).",difficulty:"medium",tags:["гемопоэз","костный мозг"]},{id:"blood-basics-017",topicId:"blood-basics",question:"Какая клетка является исходной для гемопоэза?",options:["Стволовая кроветворная клетка","Зрелый эритроцит","Тромбоцит","Лимфоцит"],correctIndex:0,explanation:"Исходной клеткой гемопоэза является стволовая кроветворная клетка, из которой образуются эритроциты, лейкоциты и тромбоциты.",difficulty:"medium",tags:["гемопоэз","стволовая клетка"]},{id:"blood-basics-018",topicId:"blood-basics",question:"Какие форменные элементы образуются в результате гемопоэза?",options:["Эритроциты, лейкоциты и тромбоциты","Только эритроциты","Альбумины, глобулины и фибриноген","Антитела и антигены"],correctIndex:0,explanation:"В результате гемопоэза образуются эритроциты, лейкоциты и тромбоциты.",difficulty:"easy",tags:["гемопоэз","форменные элементы"]},{id:"blood-basics-019",topicId:"blood-basics",question:"Какая особенность характерна для эритроцитов?",options:["Это безъядерные клетки, содержащие гемоглобин","Это ядерные клетки, обеспечивающие иммунитет","Это безъядерные пластинки, участвующие в гемостазе","Это белки плазмы крови"],correctIndex:0,explanation:"Эритроциты — безъядерные клетки крови, содержащие гемоглобин.",difficulty:"easy",tags:["эритроциты","определение"]},{id:"blood-basics-020",topicId:"blood-basics",question:"Какова норма содержания эритроцитов у мужчин?",options:["4,5–5,5 ×10¹²/л","3,8–4,8 ×10¹²/л","4–9 ×10⁹/л","150–400 ×10⁹/л"],correctIndex:0,explanation:"Норма эритроцитов у мужчин — 4,5–5,5 ×10¹²/л, у женщин — 3,8–4,8 ×10¹²/л.",difficulty:"hard",tags:["эритроциты","норма","мужчины"]},{id:"blood-basics-021",topicId:"blood-basics",question:"Какова норма содержания эритроцитов у женщин?",options:["3,8–4,8 ×10¹²/л","4,5–5,5 ×10¹²/л","4–9 ×10⁹/л","120–140 ×10¹²/л"],correctIndex:0,explanation:"Норма эритроцитов у женщин — 3,8–4,8 ×10¹²/л, у мужчин — 4,5–5,5 ×10¹²/л.",difficulty:"hard",tags:["эритроциты","норма","женщины"]},{id:"blood-basics-022",topicId:"blood-basics",question:"Какую форму имеет эритроцит?",options:["Двояковогнутого диска","Шара","Звезды с отростками","Цилиндра"],correctIndex:0,explanation:"Эритроцит имеет форму двояковогнутого диска.",difficulty:"easy",tags:["эритроциты","форма"]},{id:"blood-basics-023",topicId:"blood-basics",question:"Какова продолжительность жизни эритроцита?",options:["≈ 120 дней","≈ 7–10 дней","≈ 30 дней","≈ 1 год"],correctIndex:0,explanation:"Продолжительность жизни эритроцита составляет примерно 120 дней.",difficulty:"medium",tags:["эритроциты","продолжительность жизни"]},{id:"blood-basics-024",topicId:"blood-basics",question:"Где разрушаются эритроциты?",options:["В селезёнке и печени","В красном костном мозге","В почках","В лёгких"],correctIndex:0,explanation:"Эритроциты образуются в красном костном мозге, а разрушаются в селезёнке и печени.",difficulty:"medium",tags:["эритроциты","селезёнка","печень"]},{id:"blood-basics-025",topicId:"blood-basics",question:"Что такое гемоглобин?",options:["Сложный белок крови в составе эритроцитов, обеспечивающий перенос кислорода и частично углекислого газа","Безъядерная клетка крови","Белок плазмы, образующий фибрин","Антиген на поверхности эритроцитов"],correctIndex:0,explanation:"Гемоглобин — сложный белок крови, входящий в состав эритроцитов, который обеспечивает перенос кислорода и частично углекислого газа.",difficulty:"medium",tags:["гемоглобин","определение"]},{id:"blood-basics-026",topicId:"blood-basics",question:"Какова норма гемоглобина у мужчин?",options:["140–160 г/л","120–140 г/л","100–120 г/л","160–180 г/л"],correctIndex:0,explanation:"Норма гемоглобина у мужчин — 140–160 г/л, у женщин — 120–140 г/л.",difficulty:"hard",tags:["гемоглобин","норма","мужчины"]},{id:"blood-basics-027",topicId:"blood-basics",question:"Какова норма гемоглобина у женщин?",options:["120–140 г/л","140–160 г/л","90–110 г/л","150–170 г/л"],correctIndex:0,explanation:"Норма гемоглобина у женщин — 120–140 г/л, у мужчин — 140–160 г/л.",difficulty:"hard",tags:["гемоглобин","норма","женщины"]},{id:"blood-basics-028",topicId:"blood-basics",question:"Что обозначает аббревиатура СОЭ?",options:["Скорость оседания эритроцитов","Содержание окисленных эритроцитов","Систолический объём эритроцитов","Средний объём эритроцита"],correctIndex:0,explanation:"СОЭ — это скорость оседания эритроцитов.",difficulty:"easy",tags:["СОЭ","определение"]},{id:"blood-basics-029",topicId:"blood-basics",question:"При каких состояниях СОЭ ускоряется?",options:["При инфекционных заболеваниях, воспалительных процессах, у беременных","При обезвоживании и голодании","При понижении температуры тела","При физической нагрузке у здоровых людей"],correctIndex:0,explanation:"При инфекционных заболеваниях, воспалительных процессах и у беременных СОЭ ускорено.",difficulty:"medium",tags:["СОЭ","воспаление","клиника"]},{id:"blood-basics-030",topicId:"blood-basics",question:"Какова норма СОЭ у женщин?",options:["2–15 мм/ч","1–10 мм/ч","20–30 мм/ч","0–1 мм/ч"],correctIndex:0,explanation:"Норма СОЭ у женщин — 2–15 мм/ч, у мужчин — 1–10 мм/ч.",difficulty:"hard",tags:["СОЭ","норма","женщины"]},{id:"blood-basics-031",topicId:"blood-basics",question:"Как называется состояние при уменьшении числа эритроцитов (эритропении)?",options:["Анемия","Эритроцитоз","Лейкоцитоз","Тромбоцитоз"],correctIndex:0,explanation:"При уменьшении числа эритроцитов (эритропении) возникает анемия. При увеличении числа эритроцитов — эритроцитоз.",difficulty:"medium",tags:["эритроциты","анемия","эритропения"]},{id:"blood-basics-032",topicId:"blood-basics",question:"Как называется состояние при увеличении числа эритроцитов?",options:["Эритроцитоз","Анемия","Лейкопения","Тромбоцитопения"],correctIndex:0,explanation:"При увеличении числа эритроцитов возникает эритроцитоз, при уменьшении — анемия.",difficulty:"medium",tags:["эритроциты","эритроцитоз"]},{id:"blood-basics-033",topicId:"blood-basics",question:"Какая особенность отличает лейкоциты от эритроцитов?",options:["Лейкоциты — ядерные клетки, обеспечивающие иммунную защиту","Лейкоциты безъядерные и содержат гемоглобин","Лейкоциты — это белки плазмы","Лейкоциты переносят кислород"],correctIndex:0,explanation:"Лейкоциты — ядерные клетки крови, обеспечивающие иммунную защиту (в отличие от безъядерных эритроцитов).",difficulty:"medium",tags:["лейкоциты","определение","иммунитет"]},{id:"blood-basics-034",topicId:"blood-basics",question:"Какова норма содержания лейкоцитов?",options:["4–9 ×10⁹/л","150–400 ×10⁹/л","4,5–5,5 ×10¹²/л","120–140 ×10⁹/л"],correctIndex:0,explanation:"Норма лейкоцитов — 4–9 ×10⁹/л.",difficulty:"hard",tags:["лейкоциты","норма"]},{id:"blood-basics-035",topicId:"blood-basics",question:"Как называется увеличение числа лейкоцитов?",options:["Лейкоцитоз","Лейкопения","Эритроцитоз","Тромбоцитоз"],correctIndex:0,explanation:"Увеличение лейкоцитов — лейкоцитоз; уменьшение лейкоцитов — лейкопения.",difficulty:"medium",tags:["лейкоциты","лейкоцитоз"]},{id:"blood-basics-036",topicId:"blood-basics",question:"Что представляют собой тромбоциты?",options:["Безъядерные кровяные пластинки","Ядерные клетки иммунной защиты","Безъядерные клетки с гемоглобином","Белки свёртывания плазмы"],correctIndex:0,explanation:"Тромбоциты — безъядерные кровяные пластинки, участвующие в гемостазе.",difficulty:"medium",tags:["тромбоциты","определение"]},{id:"blood-basics-037",topicId:"blood-basics",question:"Какова норма содержания тромбоцитов?",options:["150–400 ×10⁹/л","4–9 ×10⁹/л","4,5–5,5 ×10¹²/л","40–90 ×10⁹/л"],correctIndex:0,explanation:"Норма тромбоцитов — 150–400 ×10⁹/л.",difficulty:"hard",tags:["тромбоциты","норма"]},{id:"blood-basics-038",topicId:"blood-basics",question:"Какая функция относится к тромбоцитам?",options:["Первичный гемостаз и образование тромбоцитарной пробки","Перенос кислорода к тканям","Выработка антител против инфекций","Поддержание pH крови"],correctIndex:0,explanation:"Функции тромбоцитов: первичный гемостаз, образование тромбоцитарной пробки и участие в свёртывании крови.",difficulty:"medium",tags:["тромбоциты","гемостаз","функции"]},{id:"blood-basics-039",topicId:"blood-basics",question:"Какова продолжительность жизни тромбоцитов?",options:["7–10 дней","≈ 120 дней","1–2 дня","30–40 дней"],correctIndex:0,explanation:"Продолжительность жизни тромбоцитов — 7–10 дней.",difficulty:"medium",tags:["тромбоциты","продолжительность жизни"]},{id:"blood-basics-040",topicId:"blood-basics",question:"Как называется уменьшение числа тромбоцитов?",options:["Тромбоцитопения","Тромбоцитоз","Лейкопения","Анемия"],correctIndex:0,explanation:"Увеличение тромбоцитов — тромбоцитоз; уменьшение — тромбоцитопения.",difficulty:"medium",tags:["тромбоциты","тромбоцитопения"]},{id:"blood-basics-041",topicId:"blood-basics",question:"На чём основана система групп крови AB0?",options:["На наличии агглютиногенов (A, B) на эритроцитах и агглютининов (α, β) в плазме","На наличии антигена D на эритроцитах","На количестве гемоглобина в эритроцитах","На скорости оседания эритроцитов"],correctIndex:0,explanation:"Система AB0 основана на наличии агглютиногенов (A, B) на эритроцитах и агглютининов (α, β) в плазме.",difficulty:"hard",tags:["группы крови","AB0","агглютиногены"]},{id:"blood-basics-042",topicId:"blood-basics",question:"Какая группа крови является универсальным донором?",options:["0 (I)","AB (IV)","A (II)","B (III)"],correctIndex:0,explanation:"По правилам переливания 0 (I) — универсальный донор, а AB (IV) — универсальный реципиент.",difficulty:"medium",tags:["группы крови","переливание","донор"]},{id:"blood-basics-043",topicId:"blood-basics",question:"Какая группа крови является универсальным реципиентом?",options:["AB (IV)","0 (I)","A (II)","B (III)"],correctIndex:0,explanation:"AB (IV) — универсальный реципиент, а 0 (I) — универсальный донор.",difficulty:"medium",tags:["группы крови","переливание","реципиент"]},{id:"blood-basics-044",topicId:"blood-basics",question:"Что представляет собой резус-фактор?",options:["Антиген (D), находящийся на эритроцитах","Агглютинин в плазме крови","Белок свёртывания крови","Фермент печени"],correctIndex:0,explanation:"Резус-фактор — антиген (D), находящийся на эритроцитах. При его наличии кровь Rh⁺, при отсутствии — Rh⁻.",difficulty:"medium",tags:["резус-фактор","антиген D"]},{id:"blood-basics-045",topicId:"blood-basics",question:"Что означает резус-положительная (Rh⁺) кровь?",options:["Антиген D присутствует на эритроцитах","Антиген D отсутствует на эритроцитах","В плазме есть анти-D антитела с рождения","Кровь относится к группе AB (IV)"],correctIndex:0,explanation:"Rh⁺ означает, что антиген D присутствует; Rh⁻ — что антиген D отсутствует.",difficulty:"medium",tags:["резус-фактор","Rh-положительный"]},{id:"blood-basics-046",topicId:"blood-basics",question:"При каком сочетании возникает резус-конфликт?",options:["Rh⁻ мать и Rh⁺ плод","Rh⁺ мать и Rh⁻ плод","Rh⁺ мать и Rh⁺ плод","Rh⁻ мать и Rh⁻ плод"],correctIndex:0,explanation:"Резус-конфликт возникает при Rh⁻ матери и Rh⁺ плоде: иммунная система матери воспринимает D-антиген как чужеродный и вырабатывает антитела.",difficulty:"hard",tags:["резус-конфликт","беременность"]},{id:"blood-basics-047",topicId:"blood-basics",question:"К какому осложнению может привести резус-конфликт?",options:["К гемолитической болезни новорождённого","К сахарному диабету","К гемофилии","К лейкозу"],correctIndex:0,explanation:"Резус-конфликт может привести к гемолитической болезни новорождённого.",difficulty:"medium",tags:["резус-конфликт","гемолитическая болезнь"]},{id:"blood-basics-048",topicId:"blood-basics",question:"Какова профилактика резус-конфликта?",options:["Введение анти-D иммуноглобулина","Переливание Rh⁺ крови матери","Назначение препаратов железа","Введение фибриногена"],correctIndex:0,explanation:"Профилактика резус-конфликта — введение анти-D иммуноглобулина.",difficulty:"medium",tags:["резус-конфликт","профилактика","анти-D"]},{id:"blood-basics-049",topicId:"blood-basics",question:"Какую кровь по резус-фактору можно переливать Rh⁻ пациенту?",options:["Только Rh⁻","Только Rh⁺","Как Rh⁺, так и Rh⁻","Любую, независимо от резуса"],correctIndex:0,explanation:"Rh⁻ пациенту переливают только Rh⁻ кровь, тогда как Rh⁺ пациенту можно как Rh⁺, так и Rh⁻.",difficulty:"hard",tags:["резус-фактор","переливание"]},{id:"blood-basics-050",topicId:"blood-basics",question:"При каком весе человеку нельзя сдавать кровь?",options:["Ниже 50 кг","Ниже 70 кг","Ниже 60 кг","Ниже 40 кг"],correctIndex:0,explanation:"По противопоказаниям к донорству кровь нельзя сдавать при весе ниже 50 кг, а также моложе 18 и старше 65 лет.",difficulty:"medium",tags:["донорство","противопоказания","вес"]},{id:"blood-basics-051",topicId:"blood-basics",question:"Через какое время после выздоровления от малярии можно сдавать кровь?",options:["Через 3 года","Через 5 лет","Через 6 месяцев","Через 6 недель"],correctIndex:0,explanation:"После малярии сдавать кровь можно через 3 года после выздоровления, а после туберкулёза — через 5 лет.",difficulty:"hard",tags:["донорство","противопоказания","малярия"]},{id:"blood-basics-052",topicId:"blood-basics",question:"Через какое время после родов женщина может сдавать кровь?",options:["Через 6 недель","Через 6 месяцев","Через 3 года","Сразу после родов"],correctIndex:0,explanation:"Беременность — временное противопоказание: сдавать кровь можно через 6 недель после родов. После недавних операций — через 6 месяцев.",difficulty:"hard",tags:["донорство","противопоказания","роды"]}];export{o as default};
